// Also referenced as GET /apex/status
// Registered ERC-8004 endpoint is the BASE path, e.g.
//   https://my-service.example.com/apex/
// so health probe = <agentURI.endpoint> + "health"

function register(string calldata agentURI) external returns (uint256 agentId);
function setAgentURI(uint256 agentId, string calldata agentURI) external;
function setAgentWallet(
    uint256 agentId,
    address newWallet,
    uint256 deadline,
    bytes calldata signature
) external;
function totalSupply() external view returns (uint256);
function exists(uint256 agentId) external view returns (bool);
function getAgentWallet(uint256 agentId) external view returns (address);

